CREATE OR REPLACE VIEW `vwproformaistituto` AS select 'Pagato' AS `stato`,`c`.`id` AS `fornitori_id`,`p`.`data_fattura` AS `sended`,sum(`p`.`importo`) AS `compenso`,'Storico MediaFacile' AS `compenso_descrizione` from (`provvigioni` `p` join `clientis` `c` on((`c`.`name` = `p`.`denominazione_riferimento`))) where ((`p`.`data_fattura` is not null) and (`p`.`tipo` = 'Istituto')) group by `p`.`stato`,`c`.`id`,`p`.`data_fattura`
